import{_ as o,l as r,o as e,c as l,v as t,p as s,x as i,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"诊断性预期","description":"","frontmatter":{"title":"诊断性预期","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/diagnostic-expectations.md","filePath":"econ/diagnostic-expectations.md","lastUpdated":1789023840000}'),E={name:"econ/diagnostic-expectations.md"};function c(m,a,_,f,A,B){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="诊断性预期" tabindex="-1">诊断性预期 <a class="header-anchor" href="#诊断性预期" aria-label="Permalink to &quot;诊断性预期&quot;">​</a></h1><div class="epigraph"><p>代表性启发使人按「多像」来加权状态：新闻之后，条件分布被过度代表，预期过度反应，随后均值回复。</p><footer>—— Bordalo, Gennaioli and Shleifer, Diagnostic Expectations and Credit Cycles, JFinance 2018；Kahneman and Tversky 的代表性</footer></div><p><a href="/econ/rational-inattention">上一课</a>的误差是最优噪声。本课缺口是<strong>有方向的偏差</strong>：诊断性预期。不重写 Shannon 容量，不把行为金融的全部偏差清单搬进来。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>粘性信息与疏忽偏向反应不足。信贷与股市常有反应过度与崩溃。Bordalo–Gennaioli–Shleifer：把 Kahneman–Tversky 的代表性写成对真实条件分布的扭曲：</p> \\[\\mathbb{E}^\\theta[x_{t+1}\\mid I_t]\\propto \\mathbb{E}[x_{t+1}\\mid I_t]\\left(\\frac{p(I_t\\mid\\text{典型})}{p(I_t)}\\right)^\\theta. \\]<p>好消息使「好状态」显得更代表，预报过冲，下一期修正。缺口是给宏观与信贷周期一条过度反应装置，与学习的外推相关但微观基础不同。</p><p><span class="marginnote">Bordalo, Gennaioli and Shleifer, <em>Journal of Finance</em> 2018。BGS 对宏观诊断性预期的后续。Gennaioli and Shleifer, <em>A Crisis of Beliefs</em>。本课不写限价簿上的行为做市。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在 NK 或信贷模型里把 \\(\\mathbb{E}\\) 换成诊断性 \\(\\mathbb{E}^\\theta\\)。脉冲：冲击后预期过冲，实现不及预期，出现反转。调查：预期修正对实现的回归系数可大于 RE（Coibion–Gorodnichenko 的反应不足是另一侧；诊断性瞄准过冲的序列）。信贷：对违约率的诊断性预报制造利差过窄再突然变宽。</p>',10)),(e(),s(p,null,{default:i(()=>[h(n,{id:"mermaid-26",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEWS%5B%22%E6%96%B0%E9%97%BB%22%5D%20--%3E%20REP%5B%22%E4%BB%A3%E8%A1%A8%E6%80%A7%E5%8A%A0%E6%9D%83%22%5D%0A%20%20REP%20--%3E%20OVER%5B%22%E9%A2%84%E6%9C%9F%E8%BF%87%E5%86%B2%22%5D%0A%20%20OVER%20--%3E%20REV%5B%22%E5%AE%9E%E7%8E%B0%E5%90%8E%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20REV%20--%3E%20CYC%5B%22%E4%BF%A1%E8%B4%B7%20%2F%20%E5%AE%8F%E8%A7%82%E5%91%A8%E6%9C%9F%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与适应性学习：学习也可以外推，但是渐近可到 RE；诊断性在 \\(\\theta\\gt 0\\) 时系统偏离贝叶斯，即使参数已知。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是似然比扭曲，不是容量不够。因此「更重要的变量」也会被过度代表，不会因为重要而变准——与疏忽相反。政策沟通：生动的情景可能加大 \\(\\theta\\) 方向的权重，稳定沟通需要避免代表性叙事——后课管理。HANK：若高 MPC 家庭诊断性外推收入，间接效应过冲更强。</p><p><span class="marginnote">诊断性不是唯一的过度反应模型（外推信念、自然预期 Fuster–Laibson–Mendel）。本课用 BGS 作为本课序的钉子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有资产定价异象归因于 \\(\\theta\\)。不估计实验室的代表性参数当宏观唯一校准。新闻冲击（下一课）可以是基本面的提前信息，不必是偏差。不确定性冲击是方差，不是代表性。</p><p>后课默认：反应过度可用诊断性 \\(\\mathbb{E}^\\theta\\)；与疏忽的反应不足是不同参数。下一课：即使信念是 RE，提前到来的消息也会先动后验。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>诊断性预期：代表性启发扭曲条件分布，新闻后过冲再回复。</li><li>与最优噪声、与学习外推分列。</li><li>信贷利差与宏观预期修正是自然靶。</li><li>出处：Bordalo, Gennaioli and Shleifer, <em>JF</em> 2018。</li></ul>',9))])}const x=o(E,[["render",c]]);export{u as __pageData,x as default};
